      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 10/13~15) 만 40세~49세 수도권 거주 남녀) 내비게이션 앱 서비스 사용 경험 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.29. 14:58\n조회 88\n구독\n고유링크) 10/13~15) 만 20세~49세 수도권 거주 남녀) 내비게이션 앱 서비스 사용 경험 인터뷰\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n▶조사 대상 :\n1. 운전 경력이 1년 이상이며, 주 1회 이상 자차로 운전하는?만 20세~49세 수도권 거주 남녀\n2. 차량 음성 명령 / AI 에이전트 이용 경험이 있는 자\n▶일정: 10월 13일 (화) ~ 15일 (목)중 하루 / 시간은 추후 안내드립니다\n▶소요시간: 2시간 내외 / 사례비: 6만원\n▶조사 장소 : 한국리서치 본사(강남구 논현동 9호선 언주역 인근)\n★ 신청해 주신 내용을 토대로 순차적으로 전화 드릴 예정입니다. 저희 직원과 통화 후 참여자 명단에 등록이 되셔야 참여 가능합니다.\n※ 인터뷰 전, 기존 차량 AI Agent에 관한 사진 인증과 사전과제 (간단한 질의응답 형태)가 있습니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-10-13 ~ 2026-10-15\n소요시간 120분\n사례비 60,000원\n조사방법 1:1 인터뷰 (120분)\n안내사항\n1. 해당 인터뷰는 차량 AI 에이전트 이용 경험이 있는 분들을 대상으로, AI 에이전트 이용 경험 및 신규 서비스를 사용해보고 이야기하는 조사입니다.\n2. 인터뷰 전, 기존 차량 AI Agent에 관한 사진 인증과 사전과제 (간단한 질의응답 형태)가 있습니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/794?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.29. 16:46 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 10월~) 총 40만원 ) 20대 남녀) 취미생활 관련 가정방문 조사\n좌담회알바좌담회카페\n26.09.29.\n댓글\n1\n고유링크) 10/13~15) 만 40세~49세 수도권 거주 남녀) 내비게이션 앱 서비스 사용 경험 인터뷰\n좌담회알바좌담회카페\n26.09.29.\n댓글\n1\n고유링크) 10/13~15) 만 30세~39세 수도권 거주 남녀) 내비게이션 앱 서비스 사용 경험 인터뷰\n좌담회알바좌담회카페\n26.09.29.\n댓글\n1\n고유링크) 10/13~15) 만 20세~29세 수도권 거주 남녀) 내비게이션 앱 서비스 사용 경험 인터뷰\n좌담회알바좌담회카페\n26.09.29.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
